        }
        if ($data->isInitialized('portfolioName') && null !== $data->getPortfolioName()) {
            $dataArray['portfolioName'] = $data->getPortfolioName();
        }
        foreach ($data as $key => $value) {
            if (preg_match('/.*/', (string) $key)) {
